results.audit:
kubectl get clusterrole,role -A -o json | jq -r '
  def risky_verbs: ["bind","impersonate","escalate"];

  .items[]
  | . as $r
  | [ $r.rules[]?
      | select(
          (.verbs // [] | any(. as $v | $v == "bind" or $v == "impersonate" or $v == "escalate"))
        )
      | {
          resources: ((.resources // ["*"]) | join(",")),
          verbs: ((.verbs // []) | map(select(IN("bind","impersonate","escalate"))) | join(","))
        }
    ] as $matches
  | select($matches | length > 0)
  | [
      $r.kind,
      $r.metadata.name,
      ($r.metadata.namespace // "cluster-wide"),
      ($matches | map(.resources) | unique | join(",")),
      ($matches | map(.verbs) | unique | join(","))
    ] | @tsv
' | awk -F'\t' 'BEGIN{
  printf "%-15s %-40s %-20s %-40s %-30s\n","KIND","NAME","NAMESPACE","RESOURCES","VERBS"
  print  "--------------- ---------------------------------------- -------------------- ---------------------------------------- ------------------------------"
}{
  printf "%-15s %-40s %-20s %-40s %-30s\n",$1,$2,$3,$4,$5
}'

# Flags any ClusterRoleBinding/RoleBinding that targets the user "system:anonymous".
# Prints "NO_ANONYMOUS_BINDINGS" when none are found.
(
  kubectl get clusterrolebindings -o json | jq -r '
    .items[]
    | select((.subjects | length) > 0)
    | select(any(.subjects[]?;
        .kind=="User" and .name=="system:anonymous"
      ))
    | "FOUND_ANONYMOUS:ClusterRoleBinding:\(.metadata.name):ROLE=\(.roleRef.kind)/\(.roleRef.name)"
  ';
  kubectl get rolebindings -A -o json | jq -r '
    .items[]
    | select((.subjects | length) > 0)
    | select(any(.subjects[]?;
        .kind=="User" and .name=="system:anonymous"
      ))
    | "FOUND_ANONYMOUS:RoleBinding:\(.metadata.namespace):\(.metadata.name):ROLE=\(.roleRef.kind)/\(.roleRef.name)"
  '
) | (grep -q '^FOUND_ANONYMOUS:' && cat || echo 'NO_ANONYMOUS_BINDINGS')
